# player.GetRace() -> (job, isFemale). Jobs: 0 warrior, 1 assassin, 2 sura, 3 shaman.
RACE_JOB_SEX = {
	0: (0, False), 1: (1, True), 2: (2, False), 3: (3, True),
	4: (0, True), 5: (1, False), 6: (2, True), 7: (3, False),
}
JOB_SEX_RACE = dict((value, race) for race, value in RACE_JOB_SEX.items())


def Get(vnum):
	"""Return (pvmCostume, pvpCostume, femaleIconVnum) for a sold voucher, else None."""
	try:
		return VOUCHERS.get(int(vnum))
	except (TypeError, ValueError):
		return None


def IsVoucher(vnum):
	return Get(vnum) is not None


def DisplayVnum(vnum):
	"""The costume shown for a voucher (its PvM variant); other VNUMs unchanged."""
	entry = Get(vnum)
	return entry[0] if entry else vnum


def Variants(vnum):
	entry = Get(vnum)
	return (entry[0], entry[1]) if entry else None


def IsFemaleRace(race):
	try:
		return RACE_JOB_SEX[int(race)][1]
	except (KeyError, TypeError, ValueError):
		return None


def IconVnum(vnum, race):
	"""VNUM whose icon represents the voucher for a character of this race.

	The selected costume is unisex; only its inventory icon has a separate
	female drawing. Unknown races keep the shared (male) icon.
	"""
	entry = Get(vnum)
	if not entry:
		return vnum
	if entry[2] and IsFemaleRace(race):
		return entry[2]
	return entry[0]


def PreviewRace(race, allowedJobs, allowMale=True, allowFemale=True):
	"""Race used to render a costume preview for the current character.

	Keeps the character's own class and sex when the costume allows them,
	otherwise keeps the sex on the first allowed class. Returns None when no
	combination is allowed or the race is unknown, so callers keep their
	existing default model.
	"""
	jobs = [job for job in (0, 1, 2, 3) if job in allowedJobs]
	try:
		job, female = RACE_JOB_SEX[int(race)]
	except (KeyError, TypeError, ValueError):
		return None
	if not jobs:
		return None
	if female and not allowFemale:
		female = False
	elif not female and not allowMale:
		female = True
	if (female and not allowFemale) or (not female and not allowMale):
		return None
	if job not in jobs:
		job = jobs[0]
	return JOB_SEX_RACE[(job, female)]


def WornHairIndex(player, item):
	"""msm hair index of the hair costume the character wears, else 0.

	Takes the native player/item modules so this module stays importable
	without the client. The released executable does not expose the base
	(possibly dyed) hair part to Python, so without a hair costume callers
	keep part 0, the race's default hairstyle from its msm.
	"""
	try:
		vnum = int(player.GetItemIndex(item.COSTUME_SLOT_HAIR))
		if vnum <= 0:
			return 0
		item.SelectItem(vnum)
		if item.GetItemType() != item.ITEM_TYPE_COSTUME or item.GetItemSubType() != item.COSTUME_TYPE_HAIR:
			return 0
		return max(0, int(item.GetValue(3)))
	except (AttributeError, RuntimeError, TypeError, ValueError):
		return 0


def PreviewHairIndex(previewRace, playerRace, wornHair):
	"""Hair shown with a previewed costume that is not itself a hairstyle.

	The worn hair is kept only on the character's own race: its msm index is
	not guaranteed on another race. Otherwise 0, the race's default hair.
	"""
	if wornHair and previewRace is not None and previewRace == playerRace:
		return wornHair
	return 0
